[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.2.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green:   #2D6A4F;
      --green-light: #52B788;
      --green-pale:  #D8F3DC;
      --orange:  #F4A261;
      --cream:   #FEFAE0;
      --cream-dark: #F5F0CE;
      --terra:   #E76F51;
      --text:    #1A2E22;
      --text-mid:#3D5A47;
      --text-muted: #6B8C77;
      --white:   #FFFFFF;
      --shadow-sm: 0 2px 8px rgba(45,106,79,.08);
      --shadow-md: 0 6px 24px rgba(45,106,79,.12);
      --shadow-lg: 0 12px 40px rgba(45,106,79,.16);
      --radius-sm: 12px;
      --radius-md: 20px;
      --radius-lg: 32px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', sans-serif;
      background: var(--cream);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1,h2,h3,h4,h5 { font-family: 'Nunito', sans-serif; line-height: 1.2; }

    /* ── HEADER ── */
    header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254,250,224,.92);
      backdrop-filter: blur(12px);
      border-bottom: 1.5px solid var(--cream-dark);
      padding: 0 clamp(1rem, 5vw, 3rem);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
      gap: 1rem;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: .5rem;
      text-decoration: none;
      flex-shrink: 0;
    }

    .logo-icon {
      width: 38px;
      height: 38px;
      background: var(--green);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .logo-text {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.2rem;
      color: var(--green);
      line-height: 1.1;
    }

    .logo-sub {
      font-size: .65rem;
      color: var(--text-muted);
      font-weight: 600;
      letter-spacing: .04em;
      text-transform: uppercase;
    }

    nav { display: flex; gap: .25rem; }

    nav a {
      font-family: 'Nunito', sans-serif;
      font-weight: 600;
      font-size: .95rem;
      color: var(--text-mid);
      text-decoration: none;
      padding: .45rem .85rem;
      border-radius: 8px;
      transition: background .18s, color .18s;
    }

    nav a:hover { background: var(--green-pale); color: var(--green); }

    .header-cta {
      background: var(--green);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: .9rem;
      padding: .55rem 1.2rem;
      border-radius: 10px;
      text-decoration: none;
      transition: background .18s, transform .15s;
      white-space: nowrap;
      flex-shrink: 0;
    }

    .header-cta:hover { background: #23553E; transform: translateY(-1px); }

    /* ── HERO ── */
    .hero {
      background: linear-gradient(135deg, var(--green) 0%, #3A8B64 60%, #52B788 100%);
      padding: clamp(4rem, 10vw, 7rem) clamp(1rem, 5vw, 3rem);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Ccircle cx='30' cy='30' r='4'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      pointer-events: none;
    }

    .hero-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(60px);
      opacity: .25;
      pointer-events: none;
    }

    .hero-blob-1 {
      width: 400px; height: 400px;
      background: var(--orange);
      top: -100px; right: -80px;
    }

    .hero-blob-2 {
      width: 300px; height: 300px;
      background: var(--cream);
      bottom: -100px; left: 10%;
    }

    .hero-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: .4rem;
      background: rgba(255,255,255,.15);
      border: 1.5px solid rgba(255,255,255,.3);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: .8rem;
      letter-spacing: .06em;
      text-transform: uppercase;
      padding: .35rem .85rem;
      border-radius: 50px;
      margin-bottom: 1.25rem;
    }

    .hero h1 {
      font-size: clamp(2.4rem, 5vw, 3.8rem);
      font-weight: 900;
      color: var(--white);
      margin-bottom: 1.1rem;
      letter-spacing: -.02em;
    }

    .hero h1 span { color: var(--orange); }

    .hero p {
      font-size: 1.1rem;
      color: rgba(255,255,255,.88);
      margin-bottom: 2rem;
      max-width: 480px;
      line-height: 1.7;
    }

    .hero-btns { display: flex; gap: 1rem; flex-wrap: wrap; }

    .btn-primary {
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      padding: .8rem 1.8rem;
      border-radius: var(--radius-sm);
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: .5rem;
      transition: transform .15s, box-shadow .15s, background .18s;
      box-shadow: 0 4px 14px rgba(244,162,97,.4);
    }

    .btn-primary:hover { transform: translateY(-2px); background: #e8924e; box-shadow: 0 6px 20px rgba(244,162,97,.5); }

    .btn-outline {
      background: rgba(255,255,255,.12);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      padding: .8rem 1.8rem;
      border-radius: var(--radius-sm);
      text-decoration: none;
      border: 2px solid rgba(255,255,255,.4);
      display: inline-flex;
      align-items: center;
      gap: .5rem;
      transition: background .18s, transform .15s;
    }

    .btn-outline:hover { background: rgba(255,255,255,.22); transform: translateY(-2px); }

    .hero-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      position: relative;
    }

    .hero-card {
      background: rgba(255,255,255,.14);
      border: 1.5px solid rgba(255,255,255,.25);
      border-radius: var(--radius-md);
      padding: 1.1rem;
      backdrop-filter: blur(8px);
      transition: transform .25s;
    }

    .hero-card:hover { transform: translateY(-3px); }

    .hero-card:nth-child(1) { margin-top: 2rem; }
    .hero-card:nth-child(3) { margin-top: -1rem; }

    .hero-card-emoji {
      font-size: 2.4rem;
      margin-bottom: .6rem;
      display: block;
    }

    .hero-card h4 {
      font-size: .95rem;
      font-weight: 800;
      color: var(--white);
      margin-bottom: .2rem;
    }

    .hero-card p {
      font-size: .78rem;
      color: rgba(255,255,255,.72);
      margin-bottom: 0;
      line-height: 1.4;
    }

    .hero-card .price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      color: var(--orange);
      font-size: 1rem;
      margin-top: .4rem;
    }

    /* ── SECTION COMMON ── */
    section { padding: clamp(3rem, 6vw, 5rem) clamp(1rem, 5vw, 3rem); }

    .section-inner { max-width: 1200px; margin: 0 auto; }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: .4rem;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: .78rem;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--green);
      background: var(--green-pale);
      padding: .3rem .75rem;
      border-radius: 50px;
      margin-bottom: .75rem;
    }

    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      font-weight: 900;
      color: var(--text);
      margin-bottom: .5rem;
      letter-spacing: -.02em;
    }

    .section-sub {
      font-size: 1.05rem;
      color: var(--text-muted);
      max-width: 560px;
      margin-bottom: 2.5rem;
    }

    /* ── FEATURED PRODUCTS ── */
    #featured-products { background: var(--white); }

    .carousel-wrap {
      position: relative;
    }

    .carousel-track-outer {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .carousel-track {
      display: flex;
      gap: 1.25rem;
      transition: transform .45s cubic-bezier(.25,.8,.25,1);
      will-change: transform;
    }

    .product-card {
      min-width: 240px;
      background: var(--cream);
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform .25s, box-shadow .25s;
      flex-shrink: 0;
      border: 1.5px solid var(--cream-dark);
    }

    .product-card:hover {
      transform: translateY(-5px);
      box-shadow: var(--shadow-md);
    }

    .product-img {
      width: 100%;
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      position: relative;
      overflow: hidden;
    }

    .product-img-bg {
      position: absolute;
      inset: 0;
      opacity: .15;
    }

    .product-img-emoji {
      position: relative;
      z-index: 1;
      filter: drop-shadow(0 4px 8px rgba(0,0,0,.15));
    }

    .product-body { padding: 1rem 1.1rem 1.2rem; }

    .product-tag {
      font-size: .7rem;
      font-weight: 700;
      letter-spacing: .06em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: .3rem;
    }

    .product-name {
      font-family: 'Nunito', sans-serif;
      font-size: 1rem;
      font-weight: 800;
      color: var(--text);
      margin-bottom: .35rem;
      line-height: 1.3;
    }

    .product-desc {
      font-size: .82rem;
      color: var(--text-muted);
      line-height: 1.5;
      margin-bottom: .75rem;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.2rem;
      color: var(--green);
    }

    .product-add {
      width: 32px;
      height: 32px;
      background: var(--green);
      color: var(--white);
      border: none;
      border-radius: 8px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      transition: background .18s, transform .15s;
    }

    .product-add:hover { background: #23553E; transform: scale(1.08); }

    .carousel-nav {
      display: flex;
      gap: .6rem;
      justify-content: flex-end;
      margin-top: 1.5rem;
    }

    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      background: var(--white);
      border: 2px solid var(--cream-dark);
      color: var(--text-mid);
      font-size: 1.15rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background .18s, color .18s, border-color .18s, transform .15s;
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      border-color: var(--green);
      transform: translateY(-1px);
    }

    .carousel-btn:disabled {
      opacity: .35;
      cursor: not-allowed;
      transform: none;
    }

    .carousel-dots {
      display: flex;
      gap: .45rem;
      align-items: center;
      justify-content: center;
      margin-top: 1.2rem;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--cream-dark);
      border: none;
      cursor: pointer;
      transition: background .2s, transform .2s, width .2s;
      padding: 0;
    }

    .carousel-dot.active {
      background: var(--green);
      width: 24px;
      border-radius: 4px;
    }

    /* ── SEASONAL PICKS ── */
    #seasonal-picks {
      background: linear-gradient(160deg, #FFF8E7 0%, var(--cream) 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 1.25rem;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 1.4rem;
      display: flex;
      gap: 1rem;
      align-items: flex-start;
      box-shadow: var(--shadow-sm);
      border: 1.5px solid #FFF0D4;
      transition: transform .22s, box-shadow .22s;
    }

    .seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }

    .seasonal-emoji {
      font-size: 2.2rem;
      flex-shrink: 0;
      width: 56px;
      height: 56px;
      background: #FFF3E0;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .seasonal-info h4 {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      margin-bottom: .3rem;
      color: var(--text);
      line-height: 1.3;
    }

    .seasonal-info p {
      font-size: .83rem;
      color: var(--text-muted);
      margin-bottom: .5rem;
      line-height: 1.5;
    }

    .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      color: var(--orange);
      font-size: 1.05rem;
    }

    .seasonal-badge {
      display: inline-flex;
      align-items: center;
      gap: .3rem;
      font-size: .7rem;
      font-weight: 700;
      letter-spacing: .04em;
      text-transform: uppercase;
      color: var(--terra);
      background: rgba(231,111,81,.1);
      padding: .2rem .55rem;
      border-radius: 50px;
      margin-bottom: 1.25rem;
    }

    /* ── CATEGORIES ── */
    #categories { background: var(--white); }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 1.25rem;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      cursor: pointer;
      aspect-ratio: 4 / 3;
      box-shadow: var(--shadow-sm);
      transition: transform .28s cubic-bezier(.25,.8,.25,1), box-shadow .28s;
    }

    .category-card:hover {
      transform: scale(1.04);
      box-shadow: var(--shadow-lg);
    }

    .category-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
      transition: transform .3s;
    }

    .category-card:hover .category-bg { transform: scale(1.08); }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(20,50,30,.78) 0%, rgba(20,50,30,.1) 60%, transparent 100%);
      opacity: 0;
      transition: opacity .28s;
      display: flex;
      align-items: flex-end;
      padding: 1.2rem;
    }

    .category-card:hover .category-overlay { opacity: 1; }

    .category-label-static {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: .9rem 1rem;
      background: linear-gradient(to top, rgba(20,50,30,.65) 0%, transparent 100%);
    }

    .category-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      color: var(--white);
    }

    .category-desc {
      font-size: .78rem;
      color: rgba(255,255,255,.82);
      margin-top: .2rem;
      line-height: 1.4;
    }

    /* ── BRAND HIGHLIGHTS ── */
    #highlights {
      background: linear-gradient(135deg, var(--green) 0%, #3D7A5C 100%);
      padding: clamp(2.5rem, 5vw, 4rem) clamp(1rem, 5vw, 3rem);
    }

    .highlights-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 2rem;
    }

    .highlight-item {
      text-align: center;
      padding: 1.5rem 1rem;
      border-radius: var(--radius-md);
      background: rgba(255,255,255,.08);
      border: 1.5px solid rgba(255,255,255,.15);
      transition: transform .2s, background .2s;
    }

    .highlight-item:hover {
      transform: translateY(-4px);
      background: rgba(255,255,255,.14);
    }

    .highlight-icon {
      font-size: 2rem;
      margin-bottom: .6rem;
      display: block;
    }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-size: clamp(2.2rem, 4vw, 3rem);
      font-weight: 900;
      color: var(--white);
      line-height: 1;
      margin-bottom: .35rem;
    }

    .highlight-number span { color: var(--orange); }

    .highlight-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      color: rgba(255,255,255,.9);
      margin-bottom: .3rem;
    }

    .highlight-sub {
      font-size: .82rem;
      color: rgba(255,255,255,.6);
      line-height: 1.4;
    }

    /* ── STORE LOCATOR ── */
    #store-locator { background: var(--cream); }

    .locator-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      align-items: start;
    }

    .locator-form-wrap {}

    .search-box {
      display: flex;
      gap: .6rem;
      margin-bottom: 1.5rem;
    }

    .search-input {
      flex: 1;
      padding: .85rem 1.1rem;
      border: 2px solid var(--cream-dark);
      border-radius: var(--radius-sm);
      font-family: 'Inter', sans-serif;
      font-size: 1rem;
      background: var(--white);
      color: var(--text);
      outline: none;
      transition: border-color .18s, box-shadow .18s;
    }

    .search-input:focus {
      border-color: var(--green);
      box-shadow: 0 0 0 3px rgba(45,106,79,.12);
    }

    .search-input::placeholder { color: var(--text-muted); }

    .search-btn {
      background: var(--green);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      padding: .85rem 1.6rem;
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: .45rem;
      transition: background .18s, transform .15s;
      white-space: nowrap;
    }

    .search-btn:hover { background: #23553E; transform: translateY(-1px); }

    .store-results { display: none; }
    .store-results.visible { display: block; }

    .store-card {
      background: var(--white);
      border-radius: var(--radius-sm);
      padding: 1.1rem 1.3rem;
      margin-bottom: .8rem;
      display: flex;
      align-items: flex-start;
      gap: 1rem;
      box-shadow: var(--shadow-sm);
      border: 1.5px solid var(--cream-dark);
      transition: transform .2s, box-shadow .2s;
      animation: slideUp .35s ease forwards;
    }

    .store-card:hover { transform: translateX(4px); box-shadow: var(--shadow-md); }

    @keyframes slideUp {
      from { opacity: 0; transform: translateY(12px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    .store-card:nth-child(2) { animation-delay: .08s; }
    .store-card:nth-child(3) { animation-delay: .16s; }

    .store-dot {
      width: 40px;
      height: 40px;
      background: var(--green-pale);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--green);
      font-size: 1.2rem;
      flex-shrink: 0;
    }

    .store-info h4 {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: .95rem;
      color: var(--text);
      margin-bottom: .2rem;
    }

    .store-info p {
      font-size: .82rem;
      color: var(--text-muted);
      margin-bottom: .15rem;
      line-height: 1.4;
    }

    .store-meta {
      display: flex;
      gap: .6rem;
      margin-top: .3rem;
      flex-wrap: wrap;
    }

    .store-tag {
      font-size: .72rem;
      font-weight: 700;
      letter-spacing: .03em;
      padding: .2rem .6rem;
      border-radius: 50px;
    }

    .store-tag.hours { background: var(--green-pale); color: var(--green); }
    .store-tag.dist  { background: rgba(244,162,97,.15); color: #B5621A; }

