    .map-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      color: var(--green);
      font-size: 1rem;
    }

    .map-dots {
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 40%, rgba(45,106,79,.06) 1px, transparent 1px),
