      border-color: rgba(255,255,255,.8);
      background: rgba(255,255,255,.25);
    }

    .newsletter-btn {
      background: var(--white);
      color: var(--orange);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      padding: .9rem 1.5rem;
      border: none;
      border-radius: var(--radius-sm);
      cursor: pointer;
      white-space: nowrap;
      transition: transform .15s, box-shadow .15s;
