    .newsletter-confirm {
      display: none;
      align-items: center;
      justify-content: center;
      gap: .6rem;
      background: rgba(255,255,255,.18);
      border: 2px solid rgba(255,255,255,.4);
      padding: 1rem 1.5rem;
      border-radius: var(--radius-sm);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      max-width: 480px;
      margin: 0 auto;
      animation: fadeIn .35s ease;
    }

    .newsletter-confirm.visible { display: flex; }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(8px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    /* ── FOOTER ── */
    footer {
      background: #1A2E22;
      padding: clamp(3rem, 5vw, 4.5rem) clamp(1rem, 5vw, 3rem) 2rem;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: 2.5rem;
      margin-bottom: 3rem;
    }

    .footer-brand .logo-text { color: var(--green-light); }
    .footer-brand .logo-sub  { color: rgba(255,255,255,.4); }

    .footer-tagline {
      font-size: .9rem;
      color: rgba(255,255,255,.55);
      margin-top: .8rem;
      margin-bottom: 1.25rem;
