      font-size: .88rem;
      color: rgba(255,255,255,.5);
      text-decoration: none;
      transition: color .18s;
    }

    .footer-col a:hover { color: var(--green-light); }

    .footer-bottom {
      border-top: 1.5px solid rgba(255,255,255,.08);
      padding-top: 1.5rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: .75rem;
